head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > P > validator]<br/>컴포넌트의 날짜 편집 영역에서 포커스가 해제될때 입력값 검증을 처리할 사용자 정의 함수를 설정합니다.",
    "validation" : [      
        "ioFormat 속성이 정의된 경우 사용자 정의 함수에 전달되는 입력값 포맷은 ioFormat 속성의 포맷으로 전달됩니다.",
        "사용자 정의 함수에서 입력값을 리턴할때도 ioFormat 속성의 포맷으로 설정해야 정상 동작합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {        
        validator: con_validator.getText(),
        editType : "select",
        ioFormat : "yyyyMM",
        calendarValueType : "yearMonth",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onblur"]);

    $c.gcm.createLabel('label="ioFormat=yyyyMM 설정된 상태로, 년도가 2000 년도 보다 작거나 2030 년도 보다 큰 경우 validaotor 에 의해 2000 년도로 설정됨"', '', 'label1');
    $c.gcm.createEmptyInputCalendar(cList, eList);
}



// 특정 연도로 변환하는 사용자 정의 함수
scwin.fn_validator = function(val, id) { 
    wf_body_bottom.getObj("scwin").setReturnValue("전달 파라미터 : " + val + ", " + id); 

    let year = parseInt(val.slice(0, 4), 10);
    const month = val.slice(4);

    console.log(month);

    if (year < 2000 || year > 2030)
        return "2000" + month;
    else
        return val;
}



scwin.target1_onblur = function (e) {
    let rtn = '';

    rtn = target1.getDisplayValue();
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onblur====="); 
    wf_body_bottom.getObj("scwin").setReturnValue("입력값 : " + rtn); 
}
